const {createHash,randomUUID}=require('crypto'); const {URL}=require('url');
const axios=require('axios');
const fetch=async(url,o={})=>{const r=await axios({family:4,url:String(url),method:o.method||'GET',headers:o.headers,data:o.body,timeout:o.timeout||15000,maxRedirects:o.redirect==='manual'?0:3,maxContentLength:o.maxBytes||2000000,maxBodyLength:2000000,responseType:'text',validateStatus:()=>true});return{url:r.config?.url||String(url),ok:r.status>=200&&r.status<300,status:r.status,headers:{get:k=>r.headers[k.toLowerCase()]},json:async()=>JSON.parse(r.data),text:async()=>r.data};};
const config=$vars||{};
function prepare_query_tasks(ruleInput, refs={}, current={}) { const $input={first:()=>({json:ruleInput}),all:()=> (Array.isArray(ruleInput)?ruleInput:[ruleInput]).map(json=>({json}))}; const $json=current; const $=(key)=>({all:()=>refs[key].map(json=>({json})),item:{json:refs[key][0]}});
// n8n Code node: Run Once for All Items
const campaign = $input.first().json;
const locations = [...(campaign.governorates ?? []), ...(campaign.cities ?? [])];
const sectors = campaign.sectors ?? [];
const preferredLanguages = campaign.language_preferences ?? ['fr'];
const maximumQueries = campaign.limits?.maximum_queries ?? 40;
const maximumPerSource = campaign.limits?.maximum_queries_per_source ?? maximumQueries;

const sources = (campaign.enabled_sources ?? []).filter((source) => {
  if (source.source_type === 'registry') return false;
  return ['keyword', 'sector', 'location'].some((capability) =>
    (source.capabilities ?? []).includes(capability),
  );
});

if (!campaign.campaign_id || sectors.length === 0 || locations.length === 0 || sources.length === 0) {
  throw new Error('Campaign requires campaign_id, sectors, locations, and at least one discovery source');
}

const sourceCounts = Object.fromEntries(sources.map((source) => [source.source_id, 0]));
const tasks = [];
let sourceCursor = 0;

for (const sector of sectors) {
  for (const location of locations) {
    if (tasks.length >= maximumQueries) break;

    let selected;
    for (let offset = 0; offset < sources.length; offset += 1) {
      const candidate = sources[(sourceCursor + offset) % sources.length];
      if (sourceCounts[candidate.source_id] < maximumPerSource) {
        selected = candidate;
        sourceCursor = (sourceCursor + offset + 1) % sources.length;
        break;
      }
    }
    if (!selected) break;

    const language = preferredLanguages.find((value) =>
      (selected.supported_languages ?? []).includes(value),
    );
    if (!language) continue;

    sourceCounts[selected.source_id] += 1;
    tasks.push({
      campaign_id: campaign.campaign_id,
      query_id: `q-${String(tasks.length + 1).padStart(3, '0')}`,
      source_id: selected.source_id,
      source_type: selected.source_type,
      language,
      sector,
      location,
      keywords: campaign.keywords ?? [],
      priority: 1,
      query_limit: maximumQueries,
      maximum_candidates: campaign.maximum_candidates,
    });
  }
}

return tasks.map((json) => ({ json }));


}
const j=JSON.parse($flow.state.job);
if(j.operation==='campaign'){
 j.tasks=prepare_query_tasks(j.campaign).map(x=>x.json);
 if(!j.tasks.length)throw Error('No supported research queries');
 j.queries=j.tasks.map(t=>({...t,query:`${t.sector} ${t.location}`,intent:`Discover ${t.sector} companies in ${t.location}`,priority:1,limit_per_query:j.campaign.maximum_candidates}));
 j.ai_payload={task:'Compose search queries. Return {queries:[...]}, preserving all fields except query and intent. Use each query language.',queries:j.queries};
}
return JSON.stringify(j);

