const {createHash,randomUUID}=require('crypto'); const {URL}=require('url');
const axios=require('axios');
const fetch=async(url,o={})=>{const r=await axios({family:4,url:String(url),method:o.method||'GET',headers:o.headers,data:o.body,timeout:o.timeout||15000,maxRedirects:o.redirect==='manual'?0:3,maxContentLength:o.maxBytes||2000000,maxBodyLength:2000000,responseType:'text',validateStatus:()=>true});return{url:r.config?.url||String(url),ok:r.status>=200&&r.status<300,status:r.status,headers:{get:k=>r.headers[k.toLowerCase()]},json:async()=>JSON.parse(r.data),text:async()=>r.data};};
const config=$vars||{};
function validate_composed_query(ruleInput, refs={}, current={}) { const $input={first:()=>({json:ruleInput}),all:()=> (Array.isArray(ruleInput)?ruleInput:[ruleInput]).map(json=>({json}))}; const $json=current; const $=(key)=>({all:()=>refs[key].map(json=>({json})),item:{json:refs[key][0]}});
// n8n Code node: Run Once for Each Item, directly after the Flowise HTTP Request.
const expected = $('Prepare Query Tasks').item.json;
const response = $json;
let value = response.json ?? response;

if (typeof value === 'string') {
  value = JSON.parse(value.replace(/^```json\s*|```$/g, '').trim());
}

const requiredStrings = [
  'campaign_id', 'query_id', 'source_id', 'source_type', 'language',
  'query', 'sector', 'location', 'intent',
];
for (const field of requiredStrings) {
  if (typeof value[field] !== 'string' || value[field].trim() === '') {
    throw new Error(`Invalid composed query: ${field} must be a non-empty string`);
  }
}
for (const field of ['campaign_id', 'query_id', 'source_id', 'source_type', 'language', 'sector', 'location']) {
  if (value[field] !== expected[field]) {
    throw new Error(`Invalid composed query: ${field} changed by the model`);
  }
}
if (!Number.isInteger(value.priority) || value.priority < 1 || value.priority > 5) {
  throw new Error('Invalid composed query: priority must be an integer from 1 to 5');
}

const frenchSector = {
  software: 'logiciels',
  'IT services': 'services informatiques',
};
const sectorLabel = value.language === 'fr'
  ? (frenchSector[expected.sector] ?? expected.sector)
  : expected.sector;
const generatedText = `${value.query} ${value.intent}`;
const hasWebOperator = /(^|\s)(site:|inurl:|intitle:)/i.test(value.query);
const obviousEnglishInFrench = value.language === 'fr'
  && /\b(company|companies|company discovery|find companies|software company|software|IT services)\b/i.test(generatedText);
const unsuitableForSource = value.source_type !== 'web_search' && hasWebOperator;

if (obviousEnglishInFrench || unsuitableForSource) {
  if (value.language === 'fr') {
    value.query = value.source_type === 'web_search'
      ? `entreprises de ${sectorLabel} à ${value.location} Tunisie`
      : `sociétés de ${sectorLabel} à ${value.location}`;
    value.intent = `Découvrir des sociétés de ${sectorLabel} à ${value.location}`;
  } else {
    value.query = value.source_type === 'web_search'
      ? `${sectorLabel} companies in ${value.location}, Tunisia`
      : `${sectorLabel} companies in ${value.location}`;
    value.intent = `Discover ${sectorLabel} companies in ${value.location}`;
  }
  value._composer_fallback = true;
  value._composer_warning = `Deterministic fallback used for ${value.query_id}`;
}

return { json: value };

}
const j=JSON.parse($flow.state.job);
if(j.operation==='campaign'){
 if($flow.state.ai==='true')try{const v=JSON.parse($flow.state.model);if(v.queries.length!==j.tasks.length)throw Error('Query count changed');j.queries=v.queries.map((q,i)=>validate_composed_query(null,{'Prepare Query Tasks':[j.tasks[i]]},q).json);}catch(e){j.warnings.push('Query composer rejected: deterministic queries retained');}
