if(j.operation==='campaign'){j.scoring=score_companies({campaign:j.campaign,research_plan:j.plan,official_validation:{campaign_id:j.campaign.campaign_id,companies:j.companies}})[0].json;j.companies=j.scoring.companies;j.stages.lead_scoring=j.scoring.status;}
